INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzbereiche immer physisch getrennt sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können logisch sein"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Netzbereiche für ein IT-Netzwerk plane?', 3, '[{"text": "Subnetzmasken", "correct": true, "because": "Definieren Bereiche"}, {"text": "Schnellste Installation", "correct": false, "because": "Struktur zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Netzbereiche?', 5, '[{"text": "IP-Adressbereiche", "correct": true, "because": "Definieren Segmente"}, {"text": "Routing", "correct": true, "because": "Verbindet Bereiche"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzbereiche verbessern die Sicherheit. b) Sie sind immer physisch getrennt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logische Trennung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzbereiche für ein IT-Netzwerk plane?', 4, '[{"text": "IP-Adressierung", "correct": false, "because": "Bestimmt Segmente"}, {"text": "Netzwerksicherheit", "correct": false, "because": "Schützt Bereiche"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzbereiche nur für große Netzwerke genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Netzbereichen?', 3, '[{"text": "Netzwerksegmentierung", "correct": true, "because": "Erhöht Effizienz"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Struktur wichtiger"}, {"text": "Weniger Segmente", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei Netzbereichen entscheidend?', 5, '[{"text": "Subnetze", "correct": true, "because": "Teilen Netzwerk"}, {"text": "Router", "correct": true, "because": "Verbinden Bereiche"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Netzbereiche reduzieren Netzwerkverkehr. b) Sie sind immer physisch getrennt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logische Trennung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Netzbereiche in einem IT-Netzwerk zu planen?', 4, '[{"text": "IP-Adressplan", "correct": false, "because": "Definiert Bereiche"}, {"text": "Subnetzmasken", "correct": false, "because": "Trennen Segmente"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Netzbereiche immer mit VLANs identisch?', 2, '[{"text": "Nein", "correct": true, "because": "VLANs sind eine Methode"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Netzbereiche?', 4, '[{"text": "Verbesserte Sicherheit", "correct": true, "because": "Isoliert Bereiche"}, {"text": "Reduzierter Verkehr", "correct": true, "because": "Segmentiert Netz"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzbereiche nur für kabelgebundene Netzwerke geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch WLAN"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
